<?php use VazinCMS\Security;$types=['page'=>'صفحه','destination'=>'مقصد','service'=>'خدمت سفر','article'=>'مقاله'];$statuses=['draft'=>'پیش‌نویس','published'=>'منتشرشده','archived'=>'بایگانی'];$locales=['fa'=>'فارسی','ar'=>'عربی','en'=>'English','ru'=>'Русский','tr'=>'Türkçe','hy'=>'Հայերեն','kk'=>'Қазақша','tg'=>'Тоҷикӣ','zh'=>'中文']; ?>
<section class="title"><div><h1><?=Security::e($content['title'])?></h1><p>ویرایش محتوا و SEO</p></div><a class="button secondary" href="/admin/travel">بازگشت</a></section><?php if($saved):?><div class="badge">تغییرات ذخیره شد.</div><?php endif;?><?php if($error):?><div class="alert"><?=Security::e($error)?></div><?php endif;?>
<section class="panel"><form method="post"><input type="hidden" name="_csrf" value="<?=Security::e(Security::csrf())?>"><div class="grid content-fields"><label>عنوان<input name="title" value="<?=Security::e($content['title'])?>" required></label><label>اسلاگ<input name="slug" value="<?=Security::e($content['slug'])?>" required></label><label>نوع<select name="content_type"><?php foreach($types as $v=>$l):?><option value="<?=$v?>" <?=$content['content_type']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>زبان<select name="locale"><?php foreach($locales as $v=>$l):?><option value="<?=$v?>" <?=$content['locale']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>وضعیت<select name="status"><?php foreach($statuses as $v=>$l):?><option value="<?=$v?>" <?=$content['status']===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>تصویر شاخص<input type="url" name="featured_image" value="<?=Security::e((string)$content['featured_image'])?>"></label></div><label>خلاصه<textarea name="excerpt" rows="3"><?=Security::e((string)$content['excerpt'])?></textarea></label><label>متن کامل<textarea name="body" rows="14"><?=Security::e((string)$content['body'])?></textarea></label><div class="grid seo-fields"><label>عنوان SEO<input name="meta_title" value="<?=Security::e((string)$content['meta_title'])?>"></label><label>توضیحات SEO<textarea name="meta_description" rows="3"><?=Security::e((string)$content['meta_description'])?></textarea></label></div><button>ذخیره تغییرات</button></form></section>
